<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { Mail, Download, ArrowUpRight } from '@lucide/vue'
import { useCatalog } from '../composables/catalog.js'
import { downloadBlob } from '../utils/data.js'
import PageTitle from '../components/PageTitle.vue'
import AboutFigure from '../components/AboutFigure.vue'
const { catalog, loading, error, reload } = useCatalog(), route = useRoute()
const outlineOpen = ref(true)
let media
function resizeOutline() { outlineOpen.value = media.matches }
onMounted(() => { media = matchMedia('(min-width: 1000px)'); resizeOutline(); media.addEventListener('change', resizeOutline) })
onBeforeUnmount(() => media?.removeEventListener('change', resizeOutline))
const outline = [
 { id: 'framework', label: '1. Framework', children: [{ id: 'workflow', label: '1.1 Workflow' }, { id: 'collection', label: '1.2 Data collection' }, { id: 'units', label: '1.3 Counting units' }] },
 { id: 'search', label: '2. Search' }, { id: 'browse', label: '3. Browse' },
 { id: 'genes', label: '4. Genes', children: [{ id: 'genome', label: '4.1 Genome browser' }, { id: 'features', label: '4.2 Gene features' }, { id: 'sequence', label: '4.3 Sequence regions' }] },
 { id: 'samples', label: '5. Sample details' }, { id: 'metric', label: '6. Pausing metrics' },
 { id: 'statistics', label: '7. Statistics' }, { id: 'downloads', label: '8. Downloads' },
 { id: 'contact', label: '9. Contact & data submission' }, { id: 'references', label: '10. References' }, { id: 'citation', label: '11. Citation' },
]
const counts = computed(() => [
 { key: 'profiles', label: 'Profile records', value: catalog.value?.summary.profiles },
 { key: 'studies', label: 'GEO studies', value: catalog.value?.summary.studies },
 { key: 'cells', label: 'Original cell labels', value: catalog.value?.summary.cell_labels },
 { key: 'genes', label: 'Gene / transcript PI records', value: catalog.value?.summary.transcripts },
])
const references = [
 { id: 'gro', authors: 'Core LJ, Waterfall JJ, Lis JT.', title: 'Nascent RNA sequencing reveals widespread pausing and divergent initiation at human promoters.', journal: 'Science 322, 1845–1848 (2008).', doi: '10.1126/science.1162228' },
 { id: 'pro', authors: 'Kwak H, Fuda NJ, Core LJ, Lis JT.', title: 'Precise maps of RNA polymerase reveal how promoters direct initiation and pausing.', journal: 'Science 339, 950–953 (2013).', doi: '10.1126/science.1229386' },
 { id: 'mnet', authors: 'Nojima T et al.', title: 'Mammalian NET-Seq reveals genome-wide nascent transcription coupled to RNA processing.', journal: 'Cell 161, 526–540 (2015).', doi: '10.1016/j.cell.2015.03.027' },
 { id: 'mane', authors: 'Morales J et al.', title: 'A joint NCBI and EMBL-EBI transcript set for clinical genomics and research.', journal: 'Nature 604, 310–315 (2022).', doi: '10.1038/s41586-022-04558-8' },
 { id: 'igv', authors: 'Robinson JT, Thorvaldsdóttir H, Turner D, Mesirov JP.', title: 'igv.js: an embeddable JavaScript implementation of the Integrative Genomics Viewer (IGV).', journal: 'Bioinformatics 39, btac830 (2023).', doi: '10.1093/bioinformatics/btac830' },
]
const snapshot = computed(() => catalog.value?.snapshot_date || '2026-10-09')
const citation = computed(() => `NascentAtlas. Human nascent transcription profiles and pausing-index catalog. Data snapshot: ${snapshot.value}. ${window.location.origin}/. Accessed: YYYY-MM-DD.`)
const submission = 'NascentAtlas data submission / correction\n\nContact: t01070918@163.com\nGSE accession:\nGSM accession(s):\nSRR accession(s):\nAssay (GRO-seq / PRO-seq / mNET-seq):\nCell line / condition:\nBiological replicate and technical run mapping:\nAntibody / Pol II state, if applicable:\nReference assembly and annotation version:\nPI pause-region and gene-body windows:\nNormalization, read filtering and software versions:\nQC report / signal file locations:\nSource publication DOI or PMID:\nCorrection requested, if applicable:\n'
</script>
<template>
 <div class="about-page">
  <PageTitle eyebrow="DOCUMENTATION & METHODS" title="About NascentAtlas" description="A guide to human nascent transcription data, pausing indices and connected genomic context."/>
  <div class="about-layout">
   <aside class="panel about-outline"><details :open="outlineOpen" @toggle="outlineOpen = $event.target.open"><summary>Outline</summary><nav aria-label="About page outline"><template v-for="item in outline" :key="item.id"><RouterLink :to="'/help#' + item.id" :aria-current="route.hash === '#' + item.id ? 'location' : undefined">{{ item.label }}</RouterLink><RouterLink v-for="child in item.children || []" :key="child.id" class="outline-child" :to="'/help#' + child.id" :aria-current="route.hash === '#' + child.id ? 'location' : undefined">{{ child.label }}</RouterLink></template></nav></details></aside>
   <article class="panel about-content" aria-label="About NascentAtlas guide">
    <section id="framework"><span id="scope" class="about-legacy-anchor"/><h2>1. Framework</h2>
     <p>NascentAtlas brings together human GRO-seq, PRO-seq and mNET-seq profile records to explore promoter-proximal RNA polymerase pausing. It connects existing pausing-index matrices with experimental sources, library QC, reference gene features, sequence composition and genomic signal tracks.</p>
     <p>Start from a gene, a cell label or a GEO study, inspect the corresponding measurements, and export results with their source identifiers. The current collection is a catalog snapshot; profile records retain their original experimental context.</p>
     <div v-if="loading && !catalog" class="about-data-status" role="status">Loading current catalog coverage…</div><div v-else-if="error" class="about-data-status" role="alert">{{ error }} <button class="button secondary" @click="reload">Reload coverage</button></div>
     <dl v-if="catalog" class="about-coverage"><div v-for="item in counts" :key="item.key"><dd :data-about-count="item.key">{{ item.value.toLocaleString() }}</dd><dt>{{ item.label }}</dt></div></dl>
     <h3 id="workflow">1.1 Workflow</h3>
     <ol class="about-workflow" aria-label="NascentAtlas data workflow"><li><span>01</span><h4>Collect source records</h4><p>Import assay-specific PI matrices and preserve source aliases, GSE accessions and original values.</p></li><li><span>02</span><h4>Link experimental evidence</h4><p>Connect profiles to GEO / ENA records, sequencing runs and report-derived library QC.</p></li><li><span>03</span><h4>Add genomic context</h4><p>Connect MANE annotations, reference sequences, extracted features and strand-specific signal tracks.</p></li><li><span>04</span><h4>Explore and export</h4><p>Search, filter, compare profiles and genes, then download measurements and provenance.</p></li></ol>
     <p class="about-caption">Fig. 1. Data organization in NascentAtlas. Imported PI measurements and reference-derived context remain separately documented.</p>
     <h3 id="collection">1.2 Data collection and provenance</h3><span id="status" class="about-legacy-anchor"/>
     <p>The current matrices contain <template v-if="catalog">{{ catalog.summary.assays['GRO-seq'] }} GRO-seq, {{ catalog.summary.assays['PRO-seq'] }} PRO-seq and {{ catalog.summary.assays['mNET-seq'] }} mNET-seq profiles</template><template v-else>GRO-seq, PRO-seq and mNET-seq profiles</template>. Each record keeps its source matrix, assay, original cell label and author / source label. Human-readable names such as <code>GSE128438_hESC_rep1</code> are shown throughout the interface; internal profile IDs provide stable links.</p>
     <p>The documented accession crosswalk covers 105 profiles and 152 sequencing runs, checked against official <a href="https://www.ncbi.nlm.nih.gov/geo/" target="_blank" rel="noopener">NCBI GEO</a> and <a href="https://www.ebi.ac.uk/ena/browser/home" target="_blank" rel="noopener">ENA</a> records on 14 October 2026. Sample pages provide GSM / SRR accessions, sequencing instruments, library layouts and BioProject / BioSample links. Selected records also include manually reviewed GEO experimental details.</p>
     <p>The connected genome tracks and sequence viewer use Human GRCh38.p14 and MANE RefSeq v1.5 (GRCh38). The reference build and processing parameters of the original PI matrices require separate evidence; they are not inferred from the browser reference or the assembly reported by GEO.</p>
     <h3 id="units">1.3 Counting units</h3>
     <div class="about-table-scroll"><table><thead><tr><th scope="col">Unit</th><th scope="col">Meaning in NascentAtlas</th></tr></thead><tbody><tr><th scope="row">Profile</th><td>One measurement column in a source PI matrix. It may combine multiple sequencing runs.</td></tr><tr><th scope="row">GSE / GSM / SRR</th><td>A GEO study, a GEO sample record and a sequencing run, respectively.</td></tr><tr><th scope="row">Cell label</th><td>The original source label. Related labels are retained separately, such as HEK293 and HEK293T.</td></tr><tr><th scope="row">Gene / transcript record</th><td>A gene-linked RefSeq record carrying the imported PI measurements. Gene-list summaries use their stated summary transcript.</td></tr></tbody></table></div>
     <p>Profile counts are not counts of independent biological samples. The older 93-record catalog is retained separately and is not added to the current 105-profile catalog.</p>
    </section>
    <section id="search"><h2>2. Search</h2><p>Use the home-page search box or <RouterLink to="/search">Search</RouterLink> to find a gene symbol, RefSeq transcript, GSE accession, profile alias or cell label. Results are grouped into genes / transcripts, studies and profiles, with links to their detail pages.</p><div class="about-examples"><RouterLink to="/search?q=SAMD11">SAMD11 <ArrowUpRight :size="14"/></RouterLink><RouterLink to="/search?q=NM_001385641.1">NM_001385641.1 <ArrowUpRight :size="14"/></RouterLink><RouterLink to="/search?q=GSE128438">GSE128438 <ArrowUpRight :size="14"/></RouterLink><RouterLink to="/search?q=K562">K562 <ArrowUpRight :size="14"/></RouterLink></div><AboutFigure name="search" alt="Gene search result for SAMD11" caption="Fig. 2. Search by a gene symbol and open its linked transcript record."/></section>
    <section id="browse"><h2>3. Browse</h2><p>The <RouterLink to="/samples">Browse page</RouterLink> lists sequencing profiles with their assay, cell label, GEO study and antibody annotation. Use the sidebar to combine assay, cell, antibody and study filters, or search by profile name, author or GSE. Multiple choices within the assay or cell filter are combined; different filter types are applied together.</p><ol class="about-steps"><li><b>Flat list:</b> inspect individual records, sort the table and change the number of rows per page.</li><li><b>Group by GSE:</b> review profiles within a study and open its provenance page.</li><li><b>Library QC:</b> inspect raw / clean read records, retained alignments, MAPQ≥20 retention, rRNA and clean-read GC where report evidence is available.</li></ol><p>Filters are retained in the page URL. “Export filtered records” downloads all matching records, including those on other table pages. QC retains the original report units; unavailable metrics remain unavailable.</p><AboutFigure name="browse" alt="Profile catalog with assay and cell filters beside the sequencing table" caption="Fig. 3. Browse profiles using the sidebar and switch between the profile, GSE-grouped and Library QC views."/></section>
    <section id="genes"><h2>4. Genes</h2><p>The <RouterLink to="/genes">Genes page</RouterLink> shows one gene per row, with the gene name in the first column. Remaining columns describe its summary transcript, chromosome, strand, number of measured PI profiles, median log₂ PI and sequencing-assay coverage. Search and filter by gene / transcript, assay, chromosome, strand and measurement coverage.</p><p>Open a gene to view its experimental source table, genome browser, PI distributions by assay, cell line and author, extracted gene features and sequence regions. Source filters are shared by the source table and PI views. Reference-derived features and sequence statistics describe the selected reference region.</p><AboutFigure name="genes" alt="Gene list with gene names in the first column and measured PI coverage" caption="Fig. 4. Gene-centered browsing with one gene per row and direct links to its data."/>
     <h3 id="genome">4.1 Genome browser</h3><p>The embedded <a href="https://igv.org/doc/igvjs/" target="_blank" rel="noopener">igv.js browser</a> displays MANE gene structures and sequencing signals. It initially selects three available profiles, typically one per assay. Use the cell-line selector, signal strand and expandable track picker to select up to six tracks, then choose “Apply tracks.”</p><p>Pan or zoom around the gene, enter a genomic interval, or jump to TSS, first-intron splice sites and TES using the region buttons. Track labels show the sample, assay and research source. Signal units are listed for each track; GRO / PRO aligned-read depth and mNET-seq weighted 3′ ends should be interpreted using their respective processing metadata.</p><AboutFigure name="genome-browser" alt="SAMD11 genome browser with MANE annotation and three sequencing signal tracks" caption="Fig. 4.1. Gene structures and strand-specific sequencing signal in the same genomic interval."/>
     <h3 id="features">4.2 Extracted gene features</h3><p>The documented feature table contains 30 features for 15,351 genes. Categories include gene structure, GC and CpG composition, CpG islands and pause-region sequence. Horizontal bars show the selected gene's actual feature values, with a separate scale for each category and unit; users can switch to the value table, filter features and download SVG or tabular results.</p><p>Values are shown only when the selected transcript matches the extracted reference record. Lengths are displayed in bp, fractions as percentages, and missing values remain unavailable. These are reference features, rather than model importance scores.</p><AboutFigure name="gene-features" alt="SAMD11 actual gene feature values shown as horizontal bars" caption="Fig. 4.2. Actual gene feature values grouped by biological category and measurement unit."/>
     <h3 id="sequence">4.3 Sequence regions</h3><p>Select a region to inspect reference bases in the displayed strand direction. Endpoint windows follow the MANE transcript's 5′ → 3′ direction:</p><ul><li>TSS: −600 to +600 bp, including both endpoints.</li><li>First intron, 5′ splice donor: −1000 to +1000 bp.</li><li>First intron, 3′ splice acceptor: −1000 to +1000 bp.</li><li>TES upstream: −1000 to −1 bp.</li><li>Gene body: successive 500 bp windows.</li></ul><p>ATGC composition, GC content, CpG counts / frequency and the GC profile update with the selected region. GC and base percentages exclude ambiguous bases. CpG frequency is the number of CG dinucleotides divided by valid adjacent A/T/G/C pairs. The GC profile uses non-overlapping 100 bp bins; the final bin may be shorter. Copy the displayed sequence or download FASTA for further analysis.</p><p>The Signal-weighted ATCG plot sizes each reference base by its measured strand-specific signal. Select PRO-seq, GRO-seq or mNET-seq, then choose a cell line and sample. GRO / PRO show raw aligned-read coverage depth; mNET-seq shows weighted 3′ ends. Hover or focus a base to inspect its genomic position and signal, or download the displayed values as TSV. The vertical scale stays fixed while paging through the selected region.</p><AboutFigure name="sequence-statistics" alt="Selected-region ATGC composition, GC content, CpG frequency and GC profile" caption="Fig. 4.3. Sequence statistics computed directly from the currently selected reference region."/>
    </section>
    <section id="samples"><h2>5. Sample details</h2><p>Open a profile from Browse to inspect its provenance and experimental labels, linked accessions, reference information and library QC. The PI analysis summarizes measured / missing records, the median and interquartile range, then displays a single-profile distribution and cumulative distribution.</p><p>The comparison selector accepts any other catalog profile. The distribution and cumulative plots share this selection with the sample correlation heatmap. Choosing a second profile produces a 2 × 2 heatmap; leaving the current profile alone produces its actual self-comparison. A self-comparison is not an independent replicate. Hover, focus or select a heatmap cell to inspect its signed Spearman coefficient and shared-record count.</p><p><RouterLink to="/samples/NP-7B10E7FF77">Open the GSE128438_hESC_rep1 example →</RouterLink></p><AboutFigure name="sample-comparison" alt="Two-sample Spearman heatmap with signed correlation and shared-record count" caption="Fig. 5. Compare two sample profiles using their shared measured gene / transcript records."/></section>
    <section id="metric"><h2>6. Pausing metrics and interpretation</h2><h3>6.1 What log₂ PI describes</h3><p>A pausing index generally compares promoter-proximal signal density with gene-body signal density. NascentAtlas displays the existing log₂(Pause Index) measurements from the source matrices.</p><div class="about-formula">PI = (pause-region signal / region length) / (gene-body signal / region length)<br>Displayed value = log₂(PI)</div><p>A displayed value of zero corresponds to PI = 1; positive and negative values correspond to PI above and below one. No extra logarithmic transform, missing-value filling or cross-assay normalization is applied in the displayed PI comparisons. The original calculation windows, normalization and matrix reference versions still require their own processing records.</p><h3>6.2 Grouped PI and sample correlations</h3><p>In the gene page, each dot represents one measured profile. Box summaries, where shown, describe the interquartile range and median. All mNET-seq antibody subtypes are combined in the assay view, while individual sample metadata retain their Pol II subtype labels.</p><p>Sample correlations use Spearman ranks from records measured in both profiles, requiring at least 500 shared observations. Ties use average ranks; missing values are excluded and true zero values retained. Heatmap colors show |ρ|, while pair inspection and downloads preserve signed ρ. Constant vectors or insufficient overlap produce unavailable correlations.</p><p>These views support descriptive comparisons. Assay, cell line, antibody, experimental condition and study effects are not separated by the plots, so a correlation or PI difference alone does not establish a biological cause.</p></section>
    <section id="statistics"><h2>7. Statistics</h2><p>The <RouterLink to="/statistics">Statistics page</RouterLink> summarizes assay composition, original cell-label proportions and collection coverage. Use the interactive charts to open the corresponding filtered profile records.</p><p>The collection-wide sample heatmap compares PI profiles using the same Spearman matrix as the sample detail page. Its clustered order uses average linkage with distance 1 − |ρ|. Filter by assay, cell label or GSE, inspect any pair, or download pairwise values, the plot and calculation metadata. Both axes represent sample profiles, rather than genes.</p><AboutFigure name="statistics" alt="Assay composition and cell-line composition statistics" caption="Fig. 7. Collection composition summarized using profile records as the counting unit."/></section>
    <section id="downloads"><h2>8. Downloads and reproducibility</h2><p>The <RouterLink to="/download">Download center</RouterLink> provides profile metadata, catalog JSON, matrix provenance hashes and the separate older catalog. Context-specific exports are available within the relevant data views:</p><div class="about-table-scroll"><table><thead><tr><th scope="col">View</th><th scope="col">Available exports</th></tr></thead><tbody><tr><th scope="row">Browse / Genes</th><td>All filtered profile or gene-list records as TSV.</td></tr><tr><th scope="row">Sample details</th><td>Verified metadata JSON, library QC, observed PI values and selected-sample correlation results.</td></tr><tr><th scope="row">Gene details</th><td>Measured PI values, extracted feature values / SVG and reference-region FASTA.</td></tr><tr><th scope="row">Sample correlation statistics</th><td>Pairwise TSV, heatmap PNG, method / clustering metadata and reproduction script.</td></tr></tbody></table></div><p>For reproducibility, save the catalog snapshot, source accessions, selected transcript, applied filters and relevant method / reference metadata alongside your downloaded results. Retrieve original deposited sequencing data from the linked GEO / ENA records.</p></section>
    <section id="contact"><h2>9. Contact and data submission</h2><p>For questions, corrections or candidate datasets, please contact the research groups below.</p><div class="about-contact-groups"><div><h3>Hua Shi Research Group</h3><p>Xiamen University of Technology</p></div><div><h3>Quan Zou &amp; Ruiyan Hou Research Group</h3><p>Yangtze Delta Region Institute, University of Electronic Science and Technology of China</p></div></div><a class="about-email" href="mailto:t01070918@163.com"><Mail :size="18" aria-hidden="true"/>t01070918@163.com</a><h3>Information to include</h3><p>Please provide the GSE / GSM / SRR accessions, sequencing assay, cell line and treatment, replicate / run relationships, antibody or Pol II state where relevant, reference / annotation version, PI calculation windows and normalization, QC / signal-file locations, and source publication DOI or PMID. For corrections, include the affected profile or gene and the evidence supporting the change.</p><button class="button secondary" @click="downloadBlob('NascentAtlas_submission_checklist.txt', submission, 'text/plain;charset=utf-8')"><Download :size="15"/>Download submission checklist</button></section>
    <section id="references"><h2>10. References</h2><p>Primary assay methods, reference annotation and the embedded genome viewer are described in the following publications. Cite the original experiments for the particular GSE records used in your analysis.</p><ol class="about-references"><li v-for="reference in references" :key="reference.id" :id="'reference-' + reference.id">{{ reference.authors }} {{ reference.title }} <em>{{ reference.journal }}</em> DOI: <a :href="'https://doi.org/' + reference.doi" target="_blank" rel="noopener">{{ reference.doi }}</a>.</li></ol><h3>Data resources and software documentation</h3><ul class="about-resource-links"><li><a href="https://www.ncbi.nlm.nih.gov/geo/" target="_blank" rel="noopener">NCBI Gene Expression Omnibus (GEO)</a> — study and sample records.</li><li><a href="https://www.ebi.ac.uk/ena/browser/home" target="_blank" rel="noopener">European Nucleotide Archive (ENA)</a> — sequencing-run and library metadata.</li><li><a href="https://www.ncbi.nlm.nih.gov/refseq/MANE/" target="_blank" rel="noopener">MANE reference transcript resources</a>.</li><li><a href="https://igv.org/doc/igvjs/" target="_blank" rel="noopener">igv.js documentation</a>.</li><li><a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.spearmanr.html" target="_blank" rel="noopener">SciPy Spearman correlation</a> and <a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.cluster.hierarchy.linkage.html" target="_blank" rel="noopener">hierarchical linkage</a>.</li></ul></section>
    <section id="citation"><h2>11. Citation</h2><p>When using NascentAtlas, acknowledge the resource, cite the original datasets and relevant assay / software publications, and report the data snapshot and access date. The text below is a resource-description template, rather than a journal publication citation.</p><blockquote>{{ citation }}</blockquote><button class="button secondary" @click="downloadBlob('NascentAtlas_resource_citation.txt', citation, 'text/plain;charset=utf-8')"><Download :size="15"/>Download resource description</button><p class="about-version">Catalog snapshot: {{ snapshot }} · Guide and interface examples updated 16 October 2026.</p></section>
   </article>
  </div>
 </div>
</template>
